WITH cleaned AS (SELECT id, session_id, page, event_time, CAST(duration_sec AS STRING) AS duration_sec_num, UPPER(event_type) AS event_type_upper, COALESCE(page, 'UNKNOWN') AS page_clean FROM web_events WHERE page IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, SIZE(COLLECT_SET(page)) AS num_pages, COUNT_IF(page = '/cart') AS cart_events, COUNT(*) FILTER (WHERE page = '/home') AS home_rows, GROUPING(DATE_TRUNC('WEEK', event_time)) AS gid FROM islands GROUP BY ROLLUP (DATE_TRUNC('WEEK', event_time), CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY num_pages DESC;
